import { colorNames, type PlatformModel } from './model.ts';

const HEADER =
  '// Generated by @gremorie/tokens (nx build tokens). Do not edit.';
const union = (xs: readonly string[]) => xs.map((x) => `'${x}'`).join(' | ');

export function renderIndexJs(model: PlatformModel): string {
  return [
    HEADER,
    `export const version = ${JSON.stringify(model.version)};`,
    `export const themeNames = ${JSON.stringify(model.themeNames)};`,
    `export const m3Roles = ${JSON.stringify(model.m3Roles)};`,
    `export const m3Sources = ${JSON.stringify(model.m3Sources, null, 2)};`,
    `export const themes = ${JSON.stringify(model.themes, null, 2)};`,
    '',
  ].join('\n\n');
}

export function renderIndexDts(model: PlatformModel): string {
  return [
    HEADER,
    `export type ThemeName = ${union(model.themeNames)};`,
    `export type Mode = 'light' | 'dark';`,
    `export type SemanticColorName = ${union(colorNames(model))};`,
    `export type M3Role = ${union(model.m3Roles)};`,
    [
      '/** sRGB hex (gamut mapped, #rrggbb or #rrggbbaa) and the source OKLCH. */',
      'export interface ColorValue {',
      '  readonly hex: string;',
      '  readonly oklch: string;',
      '}',
    ].join('\n'),
    [
      'export interface ThemeTokens {',
      '  readonly colors: Readonly<Record<SemanticColorName, ColorValue>>;',
      '  /** The full Material 3 ColorScheme (Compose lightColorScheme/darkColorScheme). */',
      '  readonly m3: Readonly<Record<M3Role, ColorValue>>;',
      '  /** Pixels. */',
      "  readonly radius: Readonly<Record<'base' | 'sm' | 'md' | 'lg' | 'xl', number>>;",
      "  readonly fontFamily: Readonly<Record<'sans' | 'serif' | 'mono', readonly string[]>>;",
      '}',
    ].join('\n'),
    'export declare const version: string;',
    'export declare const themeNames: readonly ThemeName[];',
    'export declare const m3Roles: readonly M3Role[];',
    [
      "/** The semantic CSS property a role takes, or 'derived' (Material Color Utilities). */",
      'export declare const m3Sources: Readonly<Record<M3Role, string>>;',
    ].join('\n'),
    'export declare const themes: Readonly<Record<ThemeName, Readonly<Record<Mode, ThemeTokens>>>>;',
    '',
  ].join('\n\n');
}
